<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';
use Artdon\MaterialCenter\Adapters\LegacyAuthAdapter;use Artdon\MaterialCenter\Adapters\LegacyProductAdapter;use Artdon\MaterialCenter\Security\PermissionService;use Artdon\MaterialCenter\Services\ProductPowerRuleService;
$context=(new LegacyAuthAdapter())->current();$user=mc_current_user();$ready=mc_table_exists('mc_product_power_rules');$allowed=$context&&(new PermissionService())->allows($context,'material_center.power.rules.view');$rules=[];$products=[];$bands=[];
if($allowed&&$ready){$rules=(new ProductPowerRuleService())->rules();$products=(new LegacyProductAdapter())->search('',100);$bands=db()->query("SELECT id,name FROM mc_power_bands WHERE status='active' ORDER BY sort_order")->fetchAll(PDO::FETCH_ASSOC);}
header('Content-Type:text/html;charset=utf-8');mc_page_start('产品电源规则','rules',$user);
