<div class="ui-page-head"><div><span class="ui-eyebrow">F9 · RULE FOUNDATION</span><h1>产品电源规则</h1><p>旧产品只读；规则独立保存到 mc_ 表，不进入报价。</p></div><button class="ui-btn" type="button" data-ui-modal-open="rule-modal">新建规则</button></div>
<?php if(!$context):?><?php mc_state('permission','需要统一登录','复用广州 ERP 账号。');?>
<?php elseif(!$ready):?><?php mc_state('config','F9 尚未安装','请先执行数据库迁移。');?>
